import React, { useState } from "react";
import { ListTransformerProps, ListReceiverProps } from "../list-block";
import { ListTranformerHeader } from "../list-transformer-header/list-transformer-header";

function doSort<T>(data: T[], comparator: (x: T) => string | number) {
  const values = data.map((d) => comparator(d));

  const sortedIndexes = data
    .map((_, idx) => idx)
    .sort((i, j) => {
      const a = values[i];
      const b = values[j];
      if (a < b) {
        return -1;
      } else if (a > b) {
        return 1;
      }
      return 0;
    });
  return sortedIndexes.map((idx) => data[idx]);
}

type SorterProps<T, SortClauses> = ListTransformerProps<T> & {
  header?: string;
  noSortLabel?: string;
  titles: (clause: SortClauses) => string;
  comparator: (x: T, clause: SortClauses) => string | number;
  sortBys: SortClauses[];
};
export function Sorter<T, SortClauses>({
  data,
  children,
  header,
  noSortLabel,
  titles,
  comparator,
  sortBys,
}: SorterProps<T, SortClauses>) {
  const [selectedSortBy, setSelectedSortBy] = useState(-1);

  const sortedData = selectedSortBy === -1 ? data : doSort(data, (x) => comparator(x, sortBys[selectedSortBy]));

  const labels = sortBys.map((v, idx) => [titles(v), idx] as const);
  const allLabels = noSortLabel ? [[noSortLabel, -1] as const, ...labels] : labels;

  const pills = allLabels.map(([title, idx]) => ({
    key: title,
    isSelected: selectedSortBy === idx,
    onClick: () => setSelectedSortBy(idx),
    children: title,
  }));

  return (
    <>
      <ListTranformerHeader pills={pills} header={header} isStickied={false} />
      {React.Children.map(children, (child) => {
        if (!React.isValidElement<ListReceiverProps<T>>(child)) {
          return child;
        }
        return React.cloneElement(child, { data: sortedData });
      })}
    </>
  );
}
