import { Meta, StoryObj } from "@storybook/react";
import { ListBlock } from "../list-block";
import { Sorter } from "./sorter";

const meta = {
  title: "Blocks/ListBlock/Sorter",
  component: Sorter,
} satisfies Meta<typeof Sorter>;

export default meta;

type TestData = {
  name: string;
  age: number;
  pets: string[];
};
const testData: TestData[] = [
  {
    name: "Johan",
    age: 17,
    pets: ["katten Misse"],
  },
  {
    name: "Vilhelm",
    age: 49,
    pets: [],
  },
  {
    name: "Sandra",
    age: 57,
    pets: ["hunden Pluto", "hamstern Rally"],
  },
  {
    name: "Mimmi",
    age: 26,
    pets: ["hunden Ralf"],
  },
];

// Cannot use `StoryObj<typeof meta>` here. Maybe because of the generic parameter?
export const Primary: StoryObj<typeof Sorter<TestData, keyof TestData>> = {
  args: {
    comparator: (data, clause) => {
      if (clause === "pets") {
        return -data.pets.length;
      }
      return data[clause];
    },
    titles: (clause) => {
      if (clause === "pets") {
        return "Antal djur";
      }
      return clause[0].toUpperCase() + clause.slice(1);
    },
    noSortLabel: "Ingen sortering vald",
    data: testData,
    sortBys: ["name", "age", "pets"],
  },
  decorators: [
    (Story, storyContext) => (
      <ListBlock
        data={storyContext.args.data}
        renderer={({ data }) => (
          <>
            {data.map((d) => (
              <div key={d.name}>
                <h3>{d.name}</h3>
                <p>Ålder: {d.age}</p>
                {d.pets.length > 0 && <p>Husdjur: {d.pets.join(", ")}</p>}
              </div>
            ))}
          </>
        )}
        sorter={(props) => <Story {...storyContext} args={{ ...storyContext.args, ...props }} />}
      />
    ),
  ],
} satisfies StoryObj<typeof Sorter<TestData, keyof TestData>>;
